CREATE FUNCTION public.merge_player_profiles (
  p_base_id      bigint,
  p_duplicate_id bigint,
  p_actor_id     uuid,
  p_actor_email  text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY INVOKER
  SET search_path TO ''
  AS $function$
declare
  v_conflicts bigint[]; v_tournaments bigint[]; v_accounts integer; v_participants integer; v_characters jsonb; v_tekken integer;
  v_base_name text; v_duplicate_name text; v_detail jsonb;
begin
  if p_base_id = p_duplicate_id then raise exception 'Los jugadores son el mismo'; end if;
  -- Consistent lock order avoids opposing merges deadlocking.
  perform 1 from public.players where id in (p_base_id,p_duplicate_id) order by id for update;
  select display_name into strict v_base_name from public.players where id = p_base_id and merged_into_player_id is null;
  select display_name into strict v_duplicate_name from public.players where id = p_duplicate_id and merged_into_player_id is null;
  select coalesce(array_agg(d.torneo_id),'{}'::bigint[]) into v_conflicts from public.tournament_participants_raw d where d.player_id = p_duplicate_id and exists(select 1 from public.tournament_participants_raw b where b.player_id = p_base_id and b.torneo_id = d.torneo_id);
  select coalesce(array_agg(torneo_id),'{}'::bigint[]) into v_tournaments from public.tournament_participants_raw where player_id = p_duplicate_id and not (torneo_id = any(v_conflicts));
  select coalesce(jsonb_agg(jsonb_build_object('character_key',character_key,'is_main',is_main)),'[]'::jsonb) into v_characters from public.player_characters where player_id = p_duplicate_id;
  update public.player_challonge_accounts set player_id = p_base_id,active = false where player_id = p_duplicate_id;
  get diagnostics v_accounts = row_count;
  update public.tournament_participants_raw set player_id = p_base_id where player_id = p_duplicate_id and not (torneo_id = any(v_conflicts));
  get diagnostics v_participants = row_count;
  insert into public.player_characters (player_id,character_key,is_main) select p_base_id,character_key,false from public.player_characters where player_id = p_duplicate_id on conflict do nothing;
  delete from public.player_characters where player_id = p_duplicate_id;
  update public.player_tekken_accounts set player_id = p_base_id where player_id = p_duplicate_id;
  get diagnostics v_tekken = row_count;
  update public.liga_participantes set player_id = p_base_id where player_id = p_duplicate_id;
  update public.players set merged_into_player_id = p_base_id where id = p_duplicate_id;
  v_detail = jsonb_build_object('base_player_id',p_base_id,'base_display_name',v_base_name,'duplicate_player_id',p_duplicate_id,'duplicate_display_name',v_duplicate_name,'cuentas_reasignadas',v_accounts,'participantes_reasignados',v_participants,'conflictos',to_jsonb(v_conflicts),'torneos_reasignados',to_jsonb(v_tournaments),'personajes_transferidos',v_characters,'tekken_cuentas_reasignadas',v_tekken,'actor_email',p_actor_email);
  insert into public.identidad_eventos(tipo,actor_user_id,detalle) values ('fusionar',p_actor_id,v_detail);
  return v_detail;
end;
$function$;

REVOKE ALL ON FUNCTION public.merge_player_profiles(bigint, bigint, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.merge_player_profiles(bigint, bigint, uuid, text) TO service_role;

CREATE FUNCTION public.save_player_profile_metadata (
  p_player_id   bigint,
  p_main        text,
  p_secondaries jsonb,
  p_accounts    jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY INVOKER
  SET search_path TO ''
  AS $function$
begin
  perform 1 from public.players where id = p_player_id and merged_into_player_id is null for update;
  if not found then raise exception 'Jugador no encontrado'; end if;
  if jsonb_typeof(p_secondaries) <> 'array' or jsonb_typeof(p_accounts) <> 'array' then raise exception 'Metadatos inválidos'; end if;
  if jsonb_array_length(p_accounts) > 20 then raise exception 'Demasiadas cuentas'; end if;
  if exists (select 1 from jsonb_array_elements_text(p_secondaries) s where s = p_main) then raise exception 'Personaje repetido'; end if;
  -- Unique constraints and row locks protect concurrent saves/claimed account IDs.
  if exists (select 1 from public.player_tekken_accounts a join jsonb_array_elements(p_accounts) item on a.tekken_id = item->>'tekkenId' where a.player_id <> p_player_id) then raise exception 'Tekken ID ya pertenece a otro jugador'; end if;
  delete from public.player_characters where player_id = p_player_id;
  if p_main is not null then insert into public.player_characters values (p_player_id,p_main,true); end if;
  insert into public.player_characters (player_id,character_key) select p_player_id, value from jsonb_array_elements_text(p_secondaries);
  delete from public.player_tekken_accounts where player_id = p_player_id and tekken_id not in (select item->>'tekkenId' from jsonb_array_elements(p_accounts) item);
  insert into public.player_tekken_accounts (player_id,tekken_id,active,is_public)
    select p_player_id,item->>'tekkenId',coalesce((item->>'active')::boolean,true),coalesce((item->>'isPublic')::boolean,false) from jsonb_array_elements(p_accounts) item
    on conflict (tekken_id) do update set active = excluded.active,is_public = excluded.is_public
    where player_tekken_accounts.player_id = excluded.player_id;
  if exists (select 1 from public.player_tekken_accounts a join jsonb_array_elements(p_accounts) item on a.tekken_id = item->>'tekkenId' where a.player_id <> p_player_id) then raise exception 'Tekken ID ya pertenece a otro jugador'; end if;
end;
$function$;

REVOKE ALL ON FUNCTION public.save_player_profile_metadata(bigint, text, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.save_player_profile_metadata(bigint, text, jsonb, jsonb) TO service_role;

